        PIX_MODAL: ['ngx-smart-modal[identifier="modalPixQrCode"] .nsm-dialog-open', '.modalPixQrCode.nsm-dialog-open'],
        PIX_QR: ['ngx-smart-modal[identifier="modalPixQrCode"] .qrCodeImg', '.modalPixQrCode.nsm-dialog-open .qrCodeImg'],
