                fields.panelHeight.value = String(d.PANEL_HEIGHT_PERCENT);
                fields.waWidth.value = String(d.WHATSAPP_CUSTOM_WIDTH);
                fields.waHeight.value = String(d.WHATSAPP_HEIGHT_PERCENT);
